INSERT INTO user_cvs (id, cv, version, user_id, created_by, updated_by) VALUES
(4,'An Nguyen — Senior Software Engineer\n\nSummary: Senior software engineer with strong experience designing scalable internal platforms and improving engineering quality across frontend and backend systems.\n\nKey Skills: System design, REST APIs, Code review, Performance tuning, Automated testing, Mentoring.\n\nExperience Highlights:\n- Led implementation of reusable application modules for employee-facing platforms.\n- Improved API reliability through validation, logging, and better error handling.\n- Mentored engineers through code reviews, technical design discussions, and delivery planning.\n\nProfile Reference: OWT-2026-004.','v1.0',4,1,1),
(5,'Binh Nguyen — Tech Lead\n\nSummary: Engineering leader focused on aligning technical execution with product goals while improving team practices and delivery predictability.\n\nKey Skills: Team leadership, System design, Backlog refinement, Risk management, API design, Release coordination.\n\nExperience Highlights:\n- Led sprint technical planning and identified implementation risks early.\n- Established development standards for testing, documentation, and reviews.\n- Supported production issue analysis and guided long-term remediation work.\n\nProfile Reference: OWT-2026-005.','v1.0',5,1,1),
(6,'Cuong Nguyen — Product Manager\n\nSummary: Product manager with experience driving internal tools from discovery through delivery and continuous improvement.\n\nKey Skills: Product strategy, Discovery workshops, Feature validation, Release planning, Communication, Process improvement.\n\nExperience Highlights:\n- Facilitated stakeholder workshops to clarify needs and success criteria.\n- Prioritized backlog items using business value, effort, and risk.\n- Prepared release notes and supported user adoption activities.\n\nProfile Reference: OWT-2026-006.','v1.0',6,1,1),
(7,'Dung Nguyen — DevOps Engineer\n\nSummary: DevOps engineer with experience automating deployment pipelines, improving observability, and supporting cloud infrastructure reliability.\n\nKey Skills: CI/CD, Docker, Kubernetes, Infrastructure as code, Monitoring, Incident response.\n\nExperience Highlights:\n- Built and maintained automated deployment pipelines for internal services.\n- Improved system monitoring with actionable alerts and dashboards.\n- Supported incident resolution and documented operational runbooks.\n\nProfile Reference: OWT-2026-007.','v1.0',7,1,1),
(8,'Giang Nguyen — QA Engineer\n\nSummary: Quality assurance specialist focused on test automation, release validation, and user-focused software quality.\n\nKey Skills: Selenium, API testing, Exploratory testing, Acceptance testing, Test documentation, Agile QA.\n\nExperience Highlights:\n- Developed automated test cases for critical application workflows.\n- Validated API behavior, edge cases, and integration scenarios.\n- Supported release readiness reviews with clear testing summaries.\n\nProfile Reference: OWT-2026-008.','v1.0',8,1,1),
(9,'Hanh Nguyen — UX Designer\n\nSummary: UX specialist with experience supporting product discovery, prototype validation, and design improvements for business tools.\n\nKey Skills: Design thinking, Prototype testing, UI design, Research synthesis, Component libraries, User feedback.\n\nExperience Highlights:\n- Facilitated design discussions with product managers and stakeholders.\n- Converted user feedback into actionable interface improvements.\n- Maintained reusable design components to improve consistency.\n\nProfile Reference: OWT-2026-009.','v1.0',9,1,1),
(10,'Hung Nguyen — Data Analyst\n\nSummary: Data analyst experienced in building dashboards, analyzing operational metrics, and turning business data into actionable insights.\n\nKey Skills: SQL, Dashboarding, Data visualization, KPI analysis, Reporting, Data quality.\n\nExperience Highlights:\n- Created KPI dashboards for monitoring business and operational performance.\n- Analyzed datasets to identify trends, anomalies, and improvement opportunities.\n- Validated reporting logic and improved data consistency across dashboards.\n\nProfile Reference: OWT-2026-010.','v1.0',10,1,1),
(11,'Khanh Nguyen — Software Engineer\n\nSummary: Full-stack engineer focused on clean implementation, maintainable code, and practical product delivery.\n\nKey Skills: JavaScript, Java, SQL, API integration, Testing, Troubleshooting.\n\nExperience Highlights:\n- Built reusable components and integrated them with backend APIs.\n- Resolved production issues by analyzing logs and application behavior.\n- Documented implementation details to support future maintenance.\n\nProfile Reference: OWT-2026-011.','v1.0',11,1,1),
(12,'Linh Nguyen — Senior Software Engineer\n\nSummary: Senior developer with a practical background in distributed systems, clean architecture, and cross-functional project delivery.\n\nKey Skills: Microservices, API integration, Architecture, Testing strategy, Documentation, Cloud services.\n\nExperience Highlights:\n- Designed backend services that support internal business workflows.\n- Created technical documentation for architecture decisions and onboarding.\n- Supported release planning, troubleshooting, and continuous improvement initiatives.\n\nProfile Reference: OWT-2026-012.','v1.0',12,1,1),
(13,'Minh Nguyen — Tech Lead\n\nSummary: Technical lead with experience guiding engineering teams, shaping architecture decisions, and ensuring reliable delivery of enterprise software.\n\nKey Skills: Technical leadership, Architecture review, Mentoring, Delivery planning, Stakeholder communication, Code quality.\n\nExperience Highlights:\n- Defined implementation approaches for complex features and integrations.\n- Reviewed pull requests and coached engineers on maintainable design patterns.\n- Coordinated with product owners to balance scope, quality, and delivery timelines.\n\nProfile Reference: OWT-2026-013.','v1.0',13,1,1),
(14,'Nam Nguyen — Product Manager\n\nSummary: Product professional focused on employee-facing platforms, workflow optimization, and cross-functional delivery.\n\nKey Skills: Requirements analysis, Backlog management, Acceptance criteria, User journeys, Product metrics, Sprint planning.\n\nExperience Highlights:\n- Created clear user stories and acceptance criteria for engineering teams.\n- Coordinated with design, engineering, and QA to deliver product increments.\n- Analyzed workflow pain points and proposed practical product improvements.\n\nProfile Reference: OWT-2026-014.','v1.0',14,1,1),
(15,'Oanh Nguyen — DevOps Engineer\n\nSummary: DevOps specialist experienced in platform operations, performance monitoring, and secure delivery workflows.\n\nKey Skills: Platform operations, Scripting, CI pipelines, Container orchestration, Backup strategy, Reliability engineering.\n\nExperience Highlights:\n- Automated recurring operational tasks and reduced manual release steps.\n- Reviewed deployment processes to improve consistency across environments.\n- Implemented health checks and monitoring for business-critical services.\n\nProfile Reference: OWT-2026-015.','v1.0',15,1,1),
(16,'Phuong Nguyen — QA Engineer\n\nSummary: QA engineer experienced in validating web applications, designing test cases, and improving release quality across agile teams.\n\nKey Skills: Manual testing, Automation testing, Regression testing, Test planning, Bug reporting, Quality assurance.\n\nExperience Highlights:\n- Created test plans and regression suites for enterprise application releases.\n- Reported defects with clear reproduction steps and business impact.\n- Collaborated with developers to verify fixes and prevent recurring issues.\n\nProfile Reference: OWT-2026-016.','v1.0',16,1,1),
(17,'Quang Nguyen — UX Designer\n\nSummary: Product designer focused on practical user experiences, workflow clarity, and accessible enterprise application design.\n\nKey Skills: Interaction design, User journeys, Figma, Information architecture, Accessibility, Design documentation.\n\nExperience Highlights:\n- Mapped user journeys and simplified complex workflow screens.\n- Prepared design specifications and interaction notes for implementation.\n- Reviewed completed UI work and provided feedback before release.\n\nProfile Reference: OWT-2026-017.','v1.0',17,1,1),
(18,'Trang Nguyen — Data Analyst\n\nSummary: Data analyst with experience supporting product and operations teams through clear reporting and practical insights.\n\nKey Skills: Analytics, Data cleaning, Visualization, Product metrics, Ad hoc analysis, Documentation.\n\nExperience Highlights:\n- Built analytical views to support product usage and adoption analysis.\n- Cleaned and transformed source data for reliable reporting outputs.\n- Presented findings in a concise format for non-technical stakeholders.\n\nProfile Reference: OWT-2026-018.','v1.0',18,1,1),
(19,'Tuan Nguyen — Software Engineer\n\nSummary: Software engineer experienced in building reliable web applications, backend services, and internal business tools.\n\nKey Skills: REST APIs, Frontend development, Backend development, Unit testing, Git, Agile delivery.\n\nExperience Highlights:\n- Implemented application features across frontend and backend modules.\n- Wrote unit tests and fixed defects found during QA validation.\n- Collaborated with teammates through code reviews and sprint ceremonies.\n\nProfile Reference: OWT-2026-019.','v1.0',19,1,1),
(20,'Vy Nguyen — Senior Software Engineer\n\nSummary: Experienced engineer focused on building maintainable enterprise applications, modernizing legacy modules, and supporting production systems.\n\nKey Skills: Java/Spring Boot, React, Database optimization, CI/CD, Agile delivery, Production support.\n\nExperience Highlights:\n- Refactored complex application flows to improve maintainability and reduce defects.\n- Optimized database queries and backend services for faster response times.\n- Collaborated with product and QA teams to deliver stable releases.\n\nProfile Reference: OWT-2026-020.','v1.0',20,1,1),
